entries[1251279] = { ["name"] = "Fel-Scarred Mana Ray", ["text"] = "1.5 sec cast\nSummons and dismisses a Fel-Scarred Mana Ray. This mount changes depending on your Riding skill and location.\n\"Surviving on Argus is not an easy task. Its leathery hide scarred by fel corruption, this mana ray is prone to fits of aggression, moreso than usual.\"\nWorld Event:\nWoW Remix: Legion" }
entries[1251281] = { ["name"] = "Bloodtooth Mana Ray", ["text"] = "1.5 sec cast\nSummons and dismisses a Bloodtooth Mana Ray. This mount changes depending on your Riding skill and location.\n\"The shattering of Argus drove this breed of mana ray to bloodthirst. It now subsists on the corrupted blood of any creatures it can sink its many teeth into.\"\nWorld Event:\nWoW Remix: Legion" }
