entries[1251283] = { ["name"] = "Albino Mana Ray", ["text"] = "1.5 sec cast\nSummons and dismisses a Albino Mana Ray. This mount changes depending on your Riding skill and location.\n\"The shattering of Argus caused the mana rays to mutate and adapt to their surroundings. Some of them abandoned their pigments in favor of strengthening their senses.\"\nWorld Event:\nWoW Remix: Legion" }
